/**
 * Guarantee-or-abstain in TypeScript (coverage.ts) against the Python checker it was compared with
 * (experiments/r11-portfolio/qpi/guarantee/checker.py), and on its own properties. All generated inputs are SYNTHETIC.
 *
 *   1. The 22 recorded research requests (rebuilt by guarantee_wire.py export, each byte-identical to its file in
 *      results/guarantee/): every compared field agrees, reason codes included, and every request hash is equal.
 *   2. Generated requests with the Python outcome recorded (coverage.fixtures.json, from 5,000 generated by
 *      scripts/coverage-differential.ts): no hard difference; where the port answers differently it is pinned there,
 *      with why, and the port must give exactly that answer.
 *   3. Properties of the port alone (fast-check): soundness under any admissible calendar, other currencies never
 *      matter, more lots never break a certificate, by-construction CVaR bounds hold for any loss distribution, a
 *      model bound is never a guarantee, nothing weaker than accepted, and no input makes it throw.
 */
import { describe, expect, it } from 'vitest'
import fc from 'fast-check'
import fixtures from './coverage.fixtures.json'
import { check, dayNum, isGuarantee, isoOf, pyFloat, requestHash, type ReserveCoverageRequest } from './coverage.ts'
import { codes, compare } from './coverageCompare.ts'
import { anyRequest, AS_OF, cvarRequest, principalRequest, reserveRequest } from './coverageGen.ts'
import { NumpyPcg64, npQuantile, npVar } from './coverageModel.ts'

type Fixture = { request: unknown; expect: Record<string, unknown>; port?: { status?: string; codes?: string[]; exposure?: boolean; why: string } }

describe('the 22 recorded research requests', () => {
  for (const c of fixtures.recorded as { name: string; request: unknown; expect: Record<string, unknown> }[]) {
    it(`${c.name}: ${String(c.expect.status)}`, () => {
      const r = compare(c.expect, check(c.request))
      expect(r.hard).toEqual([])
      expect(r.codesAgree).toBe(true)
      expect(r.exposure).toBe(false)
    })
  }
  it('all 22 are there, with every outcome the research note reports', () => {
    const by = Object.fromEntries((fixtures.recorded as { name: string; request: unknown }[]).map((c) => [c.name, check(c.request).status]))
    expect(Object.keys(by)).toHaveLength(22)
    expect(Object.values(by).filter((s) => s === 'CERTIFIED_BY_CONSTRUCTION')).toHaveLength(4)
    expect(Object.values(by).filter((s) => s === 'BOUNDED_UNDER_MODEL')).toHaveLength(1)
    expect(Object.values(by).filter((s) => s === 'ABSTAIN')).toHaveLength(17)
  })
})

describe(`generated requests against the Python checker (${fixtures.generated.length} recorded of ${fixtures.generated_of})`, () => {
  it('no hard difference, and every other difference is exactly the one pinned', () => {
    const bad: string[] = []
    for (const [i, f] of (fixtures.generated as Fixture[]).entries()) {
      const ts = check(f.request)
      const r = compare(f.expect, ts)
      if (r.hard.length) { bad.push(`#${i}: ${r.hard.join('; ')}`); continue }
      if (!f.port) { if (!r.codesAgree || r.deliberate || r.exposure) bad.push(`#${i}: unpinned difference (${codes(f.expect).join(',')} vs ${codes(ts).join(',')})`); continue }
      if (f.port.status && f.port.status !== ts.status) bad.push(`#${i}: pinned status ${f.port.status}, got ${ts.status}`)
      if (f.port.codes && JSON.stringify(f.port.codes) !== JSON.stringify(codes(ts))) bad.push(`#${i}: pinned codes ${f.port.codes.join(',')}, got ${codes(ts).join(',')}`)
      if (f.port.exposure && !r.exposure) bad.push(`#${i}: pinned a higher exposure, got none`)
    }
    expect(bad).toEqual([])
  })
  it('the pinned differences are of the named kinds only, and status differs only by the deliberate rule', () => {
    const why = (fixtures.generated as Fixture[]).filter((f) => f.port).map((f) => f.port!.why)
    // since r11-goa-1.1 the Python checker counts in-transit exposure as the port does, so that kind no longer occurs
    for (const w of why) expect(['reason precedence', 'deliberate: RISKY_SLEEVE_TOO_LARGE', 'deliberate: RISKY_SLEEVE_CURRENCY', 'in-transit exposure counted to the due date']).toContain(w)
    expect(why).toContain('reason precedence')
    expect(why).toContain('deliberate: RISKY_SLEEVE_TOO_LARGE')
    for (const f of (fixtures.generated as Fixture[]).filter((x) => x.port?.status)) expect(f.port!.codes!.some((c) => c === 'RISKY_SLEEVE_TOO_LARGE' || c === 'RISKY_SLEEVE_CURRENCY')).toBe(true)
  })
})

// ------------------------------------------------------------------------------------------------ unit behaviour
const bill = (id: string, maturity: string, extra: Record<string, unknown> = {}) => ({ id, kind: 'sovereign_zero', currency: 'INR', issuer: 'Government of India', issuer_is_currency_sovereign: true, maturity, face_per_lot_minor: 2_500_000, ...extra })
const held = (id: string, lots: number, extra: Record<string, unknown> = {}) => ({ instrument_id: id, lots, custody: 'RBI Retail Direct', custody_kind: 'sovereign_registry', ...extra })
/** Rent Rs 45,000 on 20 Dec and 20 Jan; fees Rs 2,00,000 on 20 Feb; bills of Rs 25,000 a lot (the Python tests' base case). */
const base = (over: Partial<ReserveCoverageRequest> = {}): ReserveCoverageRequest => ({
  type: 'reserve', as_of: AS_OF, currency: 'INR', horizon_days: 90,
  instruments: [bill('TB-1204', '2026-12-04'), bill('TB-0101', '2027-01-01'), bill('TB-0129', '2027-01-29')],
  positions: [held('TB-1204', 2), held('TB-0101', 2), held('TB-0129', 8)],
  obligations: [{ id: 'rent-dec', due: '2026-12-20', currency: 'INR', amount_minor: 4_500_000 }, { id: 'rent-jan', due: '2027-01-20', currency: 'INR', amount_minor: 4_500_000 }, { id: 'fees-feb', due: '2027-02-20', currency: 'INR', amount_minor: 20_000_000 }],
  bank_insured_minor: 50_000_000, ...over,
})

describe('the port on its own', () => {
  it('certifies a simple ladder by construction, with its slack, counterparties and failure conditions', () => {
    const o = check(base())
    expect(o.status).toBe('CERTIFIED_BY_CONSTRUCTION')
    expect(isGuarantee(o)).toBe(true)
    expect((o.evidence.coverage as { slack_minor: number }[]).every((r) => r.slack_minor >= 0)).toBe(true)
    expect(o.failure_conditions.some((f) => f.includes('Government of India'))).toBe(true)
    expect(o.counterparties.map((c) => c.name)).toContain('RBI Retail Direct')
  })
  it('without a calendar, cash counts from maturity + 4 days and must be in place by due - 9 days (section 5.1)', () => {
    const o = check(base())
    const row = (o.evidence.coverage as { obligation: string; fund_by: string }[]).find((r) => r.obligation === 'rent-dec')!
    expect(row.fund_by).toBe(isoOf(dayNum('2026-12-20') - 9))
    expect((o.construction[0] as { cash_available_by: string }).cash_available_by).toBe(isoOf(dayNum('2026-12-04') + 4))
  })
  it('the request hash is the Python checker\'s, deterministic and sensitive to every field', () => {
    expect(requestHash(base())).toBe(requestHash(base()))
    expect(requestHash(base())).not.toBe(requestHash(base({ horizon_days: 91 })))
    expect(pyFloat(1)).toBe('1.0'); expect(pyFloat(0.0001)).toBe('0.0001'); expect(pyFloat(0.00005)).toBe('5e-05'); expect(pyFloat(1e16)).toBe('1e+16'); expect(pyFloat(-0.0123)).toBe('-0.0123'); expect(pyFloat(123456.5)).toBe('123456.5')
  })
  it('one lot fewer and the tight plan abstains, naming the deadline it misses', () => {
    const o = check(base({ positions: [held('TB-1204', 2), held('TB-0101', 2), held('TB-0129', 7)] }))
    expect(o.status).toBe('ABSTAIN')
    expect(o.reasons[0]!.code).toBe('COVERAGE_SHORTFALL')
  })
  it('bank money counts only at the contractual level, and only from today', () => {
    const noBills = base({ positions: [], bank_cash_minor: 50_000_000, bank_name: 'Example Bank' })
    expect(codes(check(noBills))).toContain('BANK_CASH_NOT_BY_CONSTRUCTION')
    expect(check({ ...noBills, accept: ['contractual'] }).status).toBe('CERTIFIED_CONTRACTUAL')
    // due in 7 days: its funding deadline (due - 9) is already past, so even money in the account cannot be shown to
    // pay it in time under the buffer; the remedy says so (the Python checker's remedy suggested "contractual" here
    // before r11-goa-1.1)
    const soon = check({ ...noBills, accept: ['contractual'], obligations: [{ id: 'soon', due: isoOf(dayNum(AS_OF) + 7), currency: 'INR', amount_minor: 100 }] })
    expect(soon.status).toBe('ABSTAIN')
    expect(soon.remedies[0]).toMatch(/calendar/)
    expect(soon.remedies.join(' ')).not.toMatch(/accept 'contractual'/)
  })
  it('a calendar is used only when it covers the whole period; a holiday can break a tight plan', () => {
    const plan = { instruments: [bill('TB-fri', '2026-12-04')], positions: [held('TB-fri', 2)], obligations: [{ id: 'rent', due: '2026-12-07', currency: 'INR', amount_minor: 4_500_000 }] }
    const plain = { name: 'weekends only', holidays: [], covers_from: '2026-01-01', covers_to: '2027-12-31' }
    expect(check(base({ ...plan, calendar: plain })).status).toBe('CERTIFIED_BY_CONSTRUCTION')
    expect(check(base({ ...plan, calendar: { ...plain, holidays: ['2026-12-04'] } })).status).toBe('ABSTAIN')
    expect(check(base({ ...plan, calendar: { ...plain, covers_to: '2027-01-01' } })).status).toBe('ABSTAIN') // does not reach as_of + 90 + 60: the buffer applies
  })
  it('refuses a calendar with no business day (the Python checker crashed on it before r11-goa-1.1: OverflowError)', () => {
    expect(codes(check(base({ calendar: { name: 'never', holidays: [], covers_from: '2026-01-01', covers_to: '2027-12-31', weekend: [0, 1, 2, 3, 4, 5, 6] } })))).toEqual(['BAD_INPUT'])
  })
  it('refuses money that is not an integer number of minor units, and never throws on bad input', () => {
    for (const bad of [4_500_000.5, true, '45000', null]) {
      const o = check(base({ obligations: [{ id: 'rent', due: '2026-12-20', currency: 'INR', amount_minor: bad as number }] }))
      if (bad === null) expect(codes(o)).toEqual(['AMOUNT_UNCERTAIN'])
      else expect(codes(o)).toEqual(['BAD_INPUT'])
    }
    for (const junk of [null, 1, 'x', {}, { type: 'reserve' }, { type: 'cvar', holdings: 'no' }, { type: 'principal', positions: [{}] }, { type: 'cvar', as_of: '2026-11-24', base_currency: 'INR', level: 0.95, horizon_end: '2026-12-24', threshold: 0.1, holdings: [{ id: 'a', value_minor: 5, currency: 'INR', kind: 'equity_fund' }], accept: ['model_bound'], scenario_returns: 'not a list' }, { ...base(), horizon_days: 1e9 }]) {
      expect(() => check(junk)).not.toThrow()
      expect(check(junk).status).toBe('ABSTAIN')
    }
  })
  it('a cash_at_bank instrument is refused with a reason (the Python checker dropped it without one before r11-goa-1.1)', () => {
    const o = check(base({ instruments: [{ id: 'CASH', kind: 'cash_at_bank', currency: 'INR', issuer: 'Example Bank', issuer_is_currency_sovereign: false, maturity: null, face_per_lot_minor: 100_000_000 }], positions: [held('CASH', 1)] }))
    expect(codes(o)).toContain('CASH_AS_INSTRUMENT')
  })
  it('principal: a floor that matured before as_of is not a sovereign claim (the Python checker certified it before r11-goa-1.1)', () => {
    const pp = { type: 'principal' as const, as_of: AS_OF, currency: 'USD', principal_minor: 10_000_000, horizon: '2029-11-30', basis: 'nominal', tax_basis: 'before_tax', budget_minor: 10_000_000, positions: [{ instrument_id: 'Z', lots: 1000, custody: 'Broker', custody_kind: 'custodian', status: 'to_buy' as const, limit_price_per_lot_minor: 8800 }], instruments: [{ id: 'Z', kind: 'sovereign_zero', currency: 'USD', issuer: 'United States Treasury', issuer_is_currency_sovereign: true, maturity: '2029-11-15', face_per_lot_minor: 10_000 }], risky: [{ id: 'equity', value_minor: 1_200_000, currency: 'USD', limited_liability: true }] }
    const ok = check(pp)
    expect(ok.status).toBe('CERTIFIED_BY_CONSTRUCTION')
    expect(ok.evidence.max_risky_minor).toBe(1_200_000)
    expect(codes(check({ ...pp, instruments: [{ ...pp.instruments[0]!, maturity: '2026-11-20' }] }))).toContain('MATURED')
    expect(codes(check({ ...pp, risky: [{ id: 'equity', value_minor: 5_000_000, currency: 'USD', limited_liability: true }] }))).toEqual(['RISKY_SLEEVE_TOO_LARGE'])
    expect(codes(check({ ...pp, basis: 'real' }))).toContain('REAL_BASIS_NO_INSTRUMENT')
    expect(codes(check({ ...pp, risky: [{ id: 'lev', value_minor: 100, currency: 'USD', limited_liability: true, leverage: 2 }] }))).toEqual(['RISKY_SLEEVE_UNLIMITED_LIABILITY'])
  })
  it('CVaR: by construction only within the loss-bearing share; the remedy names the exact amount to move', () => {
    // the bill's face (R13): a zero counts as loss-free only up to what it pays, which must be stated
    const cv = { type: 'cvar' as const, as_of: AS_OF, base_currency: 'INR', level: 0.95, horizon_end: '2026-12-24', threshold: 0.3, holdings: [{ id: 'tbill', value_minor: 7_000_000, currency: 'INR', kind: 'sovereign_zero', maturity: '2026-12-18', issuer_is_currency_sovereign: true, face_minor: 7_050_000 }, { id: 'equity', value_minor: 3_000_000, currency: 'INR', kind: 'equity_fund' }] }
    expect(check(cv).status).toBe('CERTIFIED_BY_CONSTRUCTION')
    const o = check({ ...cv, threshold: 0.25 })
    expect(o.reasons[0]!.code).toBe('GUARANTEE_NOT_POSSIBLE_AT_THIS_EXPOSURE')
    expect(o.remedies[0]).toContain('INR 5,000.00')
  })
  it('reproduces numpy: default_rng(seed).integers, np.quantile and np.var, to the bit', () => {
    const r = new NumpyPcg64(20261124)
    expect(r.integers(120, 8)).toEqual([26, 115, 17, 115, 64, 15, 76, 41])
    expect(r.integers(120, 3)).toEqual([79, 68, 18])
    expect(new NumpyPcg64(0).integers(7, 6)).toEqual([5, 4, 3, 1, 2, 0])
    expect(npQuantile([3, 1, 2, 10], 0.95)).toBe(8.949999999999998)
    expect(npVar([0.1, 0.2, 0.35])).toBe(0.010555555555555554)
  })
})

// ------------------------------------------------------------------------------------------------ properties
/** How money really moves under a concrete calendar (independent of coverage.ts): a maturity on a non-business day
 *  pays on the next business day, then `lag` business days; a payment due on a non-business day leaves on the
 *  previous business day, `lead` business days earlier. */
function realDates(req: ReserveCoverageRequest, holidays: Set<number>) {
  const biz = (d: number) => { const wd = (((d + 3) % 7) + 7) % 7; return wd < 5 && !holidays.has(d) }
  const fwd = (d: number, n: number) => { while (!biz(d)) d++; for (let k = 0; k < n; k++) { d++; while (!biz(d)) d++ } return d }
  const back = (d: number, n: number) => { while (!biz(d)) d--; for (let k = 0; k < n; k++) { d--; while (!biz(d)) d-- } return d }
  const inst = new Map(req.instruments.map((i) => [i.id, i]))
  const ins = req.positions.map((p) => { const i = inst.get(p.instrument_id)!; return [fwd(dayNum(i.maturity!), i.payment_lag_business_days ?? 0), p.lots * i.face_per_lot_minor!] as const })
  const outs = req.obligations.map((o) => [back(dayNum(o.due), req.payment_lead_business_days ?? 1), o.amount_minor!] as const)
  return { ins, outs }
}
const maxRun = (holidays: Set<number>, a: number, b: number) => { let run = 0, best = 0; for (let d = a; d <= b; d++) { const wd = (((d + 3) % 7) + 7) % 7; if (wd >= 5 || holidays.has(d)) { run++; best = Math.max(best, run) } else run = 0 } return best }
const ladder = fc.array(fc.tuple(fc.integer({ min: 3, max: 150 }), fc.integer({ min: 1, max: 6 }), fc.integer({ min: 0, max: 1 })), { minLength: 1, maxLength: 6 })
const payments = fc.array(fc.tuple(fc.integer({ min: 10, max: 170 }), fc.integer({ min: 1, max: 15_000_000 })), { minLength: 1, maxLength: 6 })
const T = dayNum(AS_OF)
const ladderRequest = (lad: [number, number, number][], pay: [number, number][], extra: Partial<ReserveCoverageRequest> = {}): ReserveCoverageRequest => ({
  type: 'reserve', as_of: AS_OF, currency: 'INR', horizon_days: 180,
  instruments: lad.map(([m, , lag], k) => bill(`B${k}`, isoOf(T + m), { payment_lag_business_days: lag })),
  positions: lad.map(([, lots], k) => held(`B${k}`, lots)),
  obligations: pay.map(([d, a], k) => ({ id: `O${k}`, due: isoOf(T + d), currency: 'INR', amount_minor: a })), ...extra,
})

describe('properties of the port', () => {
  it('soundness: a plan certified without a calendar never runs dry under any calendar whose non-business runs fit the buffer', () => {
    let certified = 0
    fc.assert(fc.property(ladder, payments, fc.uniqueArray(fc.integer({ min: 0, max: 230 }), { maxLength: 12 }), (lad, pay, hol) => {
      const req = ladderRequest(lad, pay)
      const o = check(req)
      const holidays = new Set(hol.map((h) => T + h))
      fc.pre(maxRun(holidays, T - 10, T + 250) <= 4)
      if (o.status !== 'CERTIFIED_BY_CONSTRUCTION') return
      certified++
      const { ins, outs } = realDates(req, holidays)
      for (const [dOut] of outs) {
        const got = ins.filter(([d]) => d <= dOut).reduce((s, [, a]) => s + a, 0)
        const owed = outs.filter(([d]) => d <= dOut).reduce((s, [, a]) => s + a, 0)
        expect(got).toBeGreaterThanOrEqual(owed)
      }
    }), { numRuns: 600, seed: 20261124 })
    expect(certified).toBeGreaterThan(30) // the property is not vacuous
  })
  it('positions in another currency never change whether it certifies', () => {
    fc.assert(fc.property(ladder, payments, fc.integer({ min: 1, max: 5 }), (lad, pay, usdLots) => {
      const req = ladderRequest(lad, pay)
      const more = { ...req, instruments: [...req.instruments, { ...bill('UST', isoOf(T + 5)), currency: 'USD', issuer: 'United States Treasury', face_per_lot_minor: 10_000_000 }], positions: [...req.positions, held('UST', usdLots)] }
      expect(isGuarantee(check(more))).toBe(isGuarantee(check(req)))
    }), { numRuns: 300, seed: 7 })
  })
  it('adding lots never breaks a certificate', () => {
    fc.assert(fc.property(ladder, payments, fc.nat(), fc.integer({ min: 1, max: 4 }), (lad, pay, which, extra) => {
      const req = ladderRequest(lad, pay)
      if (check(req).status !== 'CERTIFIED_BY_CONSTRUCTION') return
      const k = which % req.positions.length
      const more = { ...req, positions: req.positions.map((p, i) => (i === k ? { ...p, lots: p.lots + extra } : p)) }
      expect(check(more).status).toBe('CERTIFIED_BY_CONSTRUCTION')
    }), { numRuns: 300, seed: 11 })
  })
  it('a by-construction CVaR bound holds for any loss distribution the declared holdings allow', () => {
    fc.assert(fc.property(fc.array(fc.tuple(fc.integer({ min: 1, max: 10_000_000 }), fc.constantFrom('zero_in', 'zero_after', 'fund', 'usd_zero')), { minLength: 1, maxLength: 6 }), fc.double({ min: 0.01, max: 0.95, noNaN: true }), fc.integer({ min: 0, max: 2 ** 31 - 1 }), (hold, thr, seed) => {
      const holdings = hold.map(([v, kind], k) => kind === 'fund' ? { id: `h${k}`, value_minor: v, currency: 'INR', kind: 'equity_fund' } : { id: `h${k}`, value_minor: v, currency: kind === 'usd_zero' ? 'USD' : 'INR', kind: 'sovereign_zero', maturity: kind === 'zero_after' ? '2027-06-01' : '2026-12-01', issuer_is_currency_sovereign: true })
      const o = check({ type: 'cvar', as_of: AS_OF, base_currency: 'INR', level: 0.95, horizon_end: '2026-12-24', threshold: thr, holdings })
      if (o.status !== 'CERTIFIED_BY_CONSTRUCTION') return
      let a = seed >>> 0
      const u = () => { a = (a + 0x6d2b79f5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4_294_967_296 }
      const total = hold.reduce((s, [v]) => s + v, 0)
      const losses = Array.from({ length: 400 }, () => hold.reduce((s, [v, kind]) => s + (kind === 'zero_in' ? 0 : v * [0, 1, u()][Math.floor(u() * 3)]!), 0) / total).sort((x, y) => y - x)
      const cvar = losses.slice(0, 20).reduce((s, x) => s + x, 0) / 20
      expect(cvar).toBeLessThanOrEqual(thr + 1e-12)
    }), { numRuns: 300, seed: 3 })
  })
  it('a model bound is never a guarantee, and nothing weaker than the accepted levels is ever returned', () => {
    fc.assert(fc.property(fc.oneof(reserveRequest, principalRequest, cvarRequest), (req) => {
      const o = check(req)
      const accept = (req as { accept: string[] }).accept
      if (o.status === 'BOUNDED_UNDER_MODEL') { expect(o.property).toMatch(/MODEL BOUND, NOT A GUARANTEE/); expect(isGuarantee(o)).toBe(false); expect(accept).toContain('model_bound') }
      if (o.status === 'CERTIFIED_CONTRACTUAL') expect(accept).toContain('contractual')
      if (!accept.includes('contractual') && !accept.includes('model_bound')) expect(['CERTIFIED_BY_CONSTRUCTION', 'ABSTAIN']).toContain(o.status)
      if (o.status === 'ABSTAIN') expect(o.reasons.length).toBeGreaterThan(0)
    }), { numRuns: 400, seed: 20261124 })
  })
  it('never throws, whatever is asked', () => {
    fc.assert(fc.property(anyRequest, (req) => { expect(() => check(req)).not.toThrow() }), { numRuns: 300, seed: 99 })
  })
})

// ------------------------------------------------------------------------------------------------ independent review
/**
 * Defects found by the independent review of the port (docs/research/qed-math-formal/20261124-coverage-port-review.md,
 * finding ids PT-nn). Each test is the counterexample that showed the defect; all inputs are SYNTHETIC.
 */
describe('independent review: counterexamples that once passed', () => {
  const zc = (extra: Record<string, unknown> = {}) => ({ id: 'Z', kind: 'sovereign_zero', currency: 'USD', issuer: 'United States Treasury', issuer_is_currency_sovereign: true, maturity: '2029-11-15', face_per_lot_minor: 10_000, ...extra })
  const buy = (extra: Record<string, unknown> = {}) => ({ instrument_id: 'Z', lots: 1000, custody: 'Broker', custody_kind: 'custodian', status: 'to_buy' as const, limit_price_per_lot_minor: 8800, ...extra })
  const pp = (over: Record<string, unknown> = {}) => ({ type: 'principal' as const, as_of: AS_OF, currency: 'USD', principal_minor: 10_000_000, horizon: '2029-11-30', basis: 'nominal', tax_basis: 'before_tax', budget_minor: 10_000_000, positions: [buy()], instruments: [zc()], risky: [{ id: 'equity', value_minor: 1_200_000, currency: 'USD', limited_liability: true }], ...over })
  const cv = (over: Record<string, unknown> = {}) => ({ type: 'cvar' as const, as_of: AS_OF, base_currency: 'INR', level: 0.95, horizon_end: '2026-12-24', threshold: 0.1, holdings: [{ id: 'tbill', value_minor: 9_000_000, currency: 'INR', kind: 'sovereign_zero', maturity: '2026-12-18', issuer_is_currency_sovereign: true }, { id: 'equity', value_minor: 1_000_000, currency: 'INR', kind: 'equity_fund' }], ...over })
  const day = (n: number) => isoOf(dayNum(AS_OF) + n)

  it('PT-01: a negative payment lag cannot bring a floor that matures after the horizon inside it', () => {
    expect(check(pp()).status).toBe('CERTIFIED_BY_CONSTRUCTION')
    // matures 2029-12-04, four days after the horizon; with lag -2 the buffer put its cash on 2029-11-28
    expect(codes(check(pp({ instruments: [zc({ maturity: '2029-12-04', payment_lag_business_days: -2 })] })))).toContain('BAD_INPUT')
    expect(codes(check(pp({ instruments: [zc({ payment_lag_business_days: 0.5 })] })))).toContain('BAD_INPUT')
  })
  it('PT-02: a purchase at a limit price of zero or less is refused (it priced the floor at nothing, or below)', () => {
    expect(codes(check(pp({ positions: [buy({ limit_price_per_lot_minor: 0 })] })))).toEqual(['NO_LIMIT_PRICE'])
    const neg = check(pp({ positions: [buy({ limit_price_per_lot_minor: -8800 })], risky: [{ id: 'equity', value_minor: 15_000_000, currency: 'USD', limited_liability: true }] }))
    expect(neg.status).toBe('ABSTAIN') // it certified, with room for USD 188,000 of risk inside a USD 100,000 budget
    expect(codes(neg)).toContain('NO_LIMIT_PRICE')
    const rv = check(base({ positions: [held('TB-1204', 2, { status: 'to_buy', limit_price_per_lot_minor: 0 })], obligations: [{ id: 'rent-dec', due: '2026-12-20', currency: 'INR', amount_minor: 4_500_000 }], budget_minor: 0 }))
    expect(codes(rv)).toEqual(['NO_LIMIT_PRICE'])
  })
  it('PT-03: custody must be of a recognised kind (section 5.1: "with identified custody")', () => {
    for (const kind of ['mattress', null, '']) {
      const o = check(base({ positions: [held('TB-1204', 2, { custody_kind: kind }), held('TB-0101', 2, { custody_kind: kind }), held('TB-0129', 8, { custody_kind: kind })] }))
      expect(o.status).toBe('ABSTAIN')
      expect(codes(o)).toContain('CUSTODY_UNKNOWN')
    }
  })
  it('PT-04: a negative leverage (a short) has no loss bound, and a leverage that is not a number is refused', () => {
    const short = check(cv({ holdings: [cv().holdings[0], { id: 'short', value_minor: 1_000_000, currency: 'INR', kind: 'equity_fund', leverage: -2 }] }))
    expect(short.status).toBe('ABSTAIN')
    expect(short.reasons[0]!.detail).toMatch(/unbounded/)
    expect(codes(check(cv({ holdings: [cv().holdings[0], { id: 'lev', value_minor: 1_000_000, currency: 'INR', kind: 'equity_fund', leverage: null }] })))).toEqual(['BAD_INPUT'])
    expect(codes(check(pp({ risky: [{ id: 'short', value_minor: 100, currency: 'USD', limited_liability: true, leverage: -1 }] })))).toEqual(['RISKY_SLEEVE_UNLIMITED_LIABILITY'])
  })
  it('PT-05: a real-terms floor must name its index (section 5.1: "the index is named")', () => {
    const tips = (index: string | null) => zc({ kind: 'sovereign_inflation_zero', index, index_lag_months: index ? 3 : null })
    const real = (index: string | null) => check(pp({ basis: 'real', instruments: [tips(index)], positions: [buy({ limit_price_per_lot_minor: 9600 })], risky: [{ id: 'equity', value_minor: 400_000, currency: 'USD', limited_liability: true }] }))
    expect(real('CPI-U NSA').status).toBe('ABSTAIN') // pays 2029-11-15, before the horizon: REAL_FLOOR_PAYS_EARLY (R13)
    expect(check(pp({ basis: 'real', instruments: [zc({ kind: 'sovereign_inflation_zero', index: 'CPI-U NSA', index_lag_months: 3, maturity: '2029-11-30' })], positions: [buy({ limit_price_per_lot_minor: 9600 })], risky: [{ id: 'equity', value_minor: 400_000, currency: 'USD', limited_liability: true }] })).status).toBe('CERTIFIED_BY_CONSTRUCTION')
    expect(real(null).status).toBe('ABSTAIN')
    expect(codes(real(null))).toContain('TERMS_INCOMPLETE')
  })
  it('PT-06: malformed flags and lists are refused, not read by JavaScript truthiness', () => {
    expect(check(base({ obligations: {} as never })).status).toBe('ABSTAIN') // was a certificate over no obligations
    expect(codes(check(base({ obligations: {} as never })))).toEqual(['BAD_INPUT'])
    expect(codes(check(base({ instruments: [bill('TB-1204', '2026-12-04', { issuer: 'A State Government', issuer_is_currency_sovereign: 'false' }), bill('TB-0101', '2027-01-01'), bill('TB-0129', '2027-01-29')] })))).toEqual(['BAD_INPUT'])
    expect(codes(check(base({ positions: [held('TB-1204', 2, { status: 'sold' }), held('TB-0101', 2), held('TB-0129', 8)] })))).toEqual(['BAD_INPUT'])
    expect(codes(check(base({ positions: [held('TB-1204', 2, { hold_to_maturity: 'yes' }), held('TB-0101', 2), held('TB-0129', 8)] })))).toEqual(['BAD_INPUT'])
    expect(codes(check(pp({ risky: [{ id: 'equity', value_minor: 1_200_000, currency: 'USD', limited_liability: 'true' }] })))).toEqual(['BAD_INPUT'])
    expect(codes(check(cv({ holdings: [{ ...cv().holdings[0], hold_to_maturity: 1 }, cv().holdings[1]] })))).toEqual(['BAD_INPUT'])
  })
  it('PT-07: a floor paying before the horizon does not establish a real floor at the horizon (R13: refused, not stated)', () => {
    const tips = zc({ id: 'TIPS-P', kind: 'sovereign_inflation_zero', maturity: '2027-01-15', index: 'CPI-U NSA', index_lag_months: 3 })
    const o = check(pp({ basis: 'real', instruments: [tips], positions: [buy({ instrument_id: 'TIPS-P', limit_price_per_lot_minor: 9900 })], risky: [] }))
    expect(o.status).toBe('ABSTAIN')
    expect(codes(o)).toContain('REAL_FLOOR_PAYS_EARLY')
    expect(o.alternatives.join(' ')).toMatch(/nominal, before tax/)
  })
  it('PT-08: remedies are true and possible: a deadline of today, a deadline inside the buffer, an exact purchase', () => {
    // funding deadline = as_of: money already in the account does count (and certifies, contractually)
    const today = check(base({ positions: [], obligations: [{ id: 'soon', due: day(9), currency: 'INR', amount_minor: 100 }] }))
    expect(today.remedies.join(' ')).toMatch(/money already in the payment account/)
    expect(today.remedies.join(' ')).not.toMatch(/no money already in the account/)
    expect(check(base({ positions: [], obligations: [{ id: 'soon', due: day(9), currency: 'INR', amount_minor: 100 }], bank_cash_minor: 100, bank_name: 'Example Bank', accept: ['contractual'] })).status).toBe('CERTIFIED_CONTRACTUAL')
    // funding deadline as_of + 2: no bill bought now can count by then (one maturing tomorrow counts from as_of + 5)
    const near = check(base({ positions: [], obligations: [{ id: 'near', due: day(11), currency: 'INR', amount_minor: 100 }] }))
    expect(near.remedies.join(' ')).toMatch(/no bill bought now pays out by its funding deadline/)
    expect(near.remedies.join(' ')).toContain(day(5))
    expect(near.evidence.remedy_buy).toBeUndefined()
    expect(check(base({ instruments: [bill('TB-next', day(1))], positions: [held('TB-next', 1)], obligations: [{ id: 'near', due: day(11), currency: 'INR', amount_minor: 100 }] })).status).toBe('ABSTAIN')
    // a purchase remedy names the latest maturity that still counts, and following it certifies
    const short = check(base({ positions: [held('TB-1204', 2), held('TB-0101', 2), held('TB-0129', 7)] }))
    const rb = short.evidence.remedy_buy as { face_minor: number; mature_on_or_before: string; cash_by: string }
    expect(rb).toEqual({ face_minor: 1_500_000, mature_after: AS_OF, mature_on_or_before: '2027-02-07', cash_by: '2027-02-11' })
    expect(short.remedies.join(' ')).toContain('2027-02-07')
    // "accept 'contractual'" is offered when the request's own bank money would cover it (it was never offered)
    const cash = check(base({ positions: [], bank_cash_minor: 50_000_000, bank_name: 'Example Bank' }))
    expect(cash.remedies.join(' ')).toMatch(/accept 'contractual'/)
    // principal: the floor must pay by the horizon, so mature by horizon - 4 under the buffer, not "by the horizon"
    const late = check(pp({ instruments: [zc({ maturity: '2029-11-30' })] }))
    expect(late.remedies[0]).toContain('on or before 2029-11-26')
  })
  it('PT-08: following the purchase remedy certifies, and one minor unit less does not (exact and minimal)', () => {
    let used = 0
    fc.assert(fc.property(ladder, payments, (lad, pay) => {
      const req = ladderRequest(lad, pay)
      const o = check(req)
      if (o.status !== 'ABSTAIN' || codes(o).join() !== 'COVERAGE_SHORTFALL') return
      const rows = o.evidence.coverage as { fund_by: string; slack_minor: number }[]
      const first = rows.find((x) => x.slack_minor < 0)!
      const rb = o.evidence.remedy_buy as { face_minor: number; mature_on_or_before: string; cash_by: string } | undefined
      if (dayNum(first.fund_by) - 4 <= dayNum(AS_OF)) { expect(rb === undefined || rb.cash_by !== first.fund_by).toBe(true); return }
      used++
      // independent of the port: the latest maturity is the deadline minus the 4-day run; the face is the largest gap
      expect(rb).toBeDefined()
      expect(rb!.mature_on_or_before).toBe(isoOf(dayNum(first.fund_by) - 4))
      expect(rb!.face_minor).toBe(Math.max(...rows.map((x) => -x.slack_minor)))
      const add = (face: number) => ({ ...req, instruments: [...req.instruments, bill('REMEDY', rb!.mature_on_or_before, { face_per_lot_minor: face })], positions: [...req.positions, held('REMEDY', 1)] })
      expect(check(add(rb!.face_minor)).status).toBe('CERTIFIED_BY_CONSTRUCTION')
      if (rb!.face_minor > 1) expect(check(add(rb!.face_minor - 1)).status).toBe('ABSTAIN')
    }), { numRuns: 400, seed: 20261124 })
    expect(used).toBeGreaterThan(30)
  })
  it('PT-09: the tax on accretion is ceil(rate x accretion), as the Python checker computes it, never one unit less', () => {
    const o = check(pp({ tax_basis: 'after_tax', tax_timing: 'on_payout', max_tax_rate: 0.3000000000001, principal_minor: 17_000, budget_minor: 20_000, risky: [], instruments: [zc({ face_per_lot_minor: 20_000 })], positions: [buy({ lots: 1, limit_price_per_lot_minor: 10_000 })] }))
    expect(o.evidence.need_minor).toBe(20_001) // 17,000 + ceil(0.3000000000001 x 10,000) = 17,000 + 3,001
    expect(codes(o)).toEqual(['FLOOR_SHORT'])
  })
  it('PT-10: sums past 2^53 minor units are refused in principal and CVaR requests too, not rounded', () => {
    const big = check(pp({ principal_minor: 2 ** 53 - 1, fees_from_account_minor: 2, budget_minor: 2 ** 53 - 1, risky: [], instruments: [zc({ face_per_lot_minor: 2 ** 43 })], positions: [buy({ lots: 1024, status: 'held', limit_price_per_lot_minor: null })] }))
    expect(codes(big)).toEqual(['BAD_INPUT']) // face 2^53 against a need of 2^53 + 1 was certified
    expect(codes(check(cv({ holdings: [{ id: 'a', value_minor: 2 ** 53 - 1, currency: 'INR', kind: 'equity_fund' }, { id: 'b', value_minor: 2 ** 53 - 1, currency: 'INR', kind: 'equity_fund' }] })))).toEqual(['BAD_INPUT'])
  })
  it('PT-11: another currency, even one the checker does not format, never changes the outcome; long calendars are read', () => {
    const chf = { ...bill('CHF-1', '2026-12-01'), currency: 'CHF', issuer: 'Swiss Confederation' }
    expect(check(base({ instruments: [...base().instruments, chf], positions: [...base().positions, held('CHF-1', 1)] })).status).toBe('CERTIFIED_BY_CONSTRUCTION')
    const long = { name: 'forty years', holidays: Array.from({ length: 600 }, (_, k) => day(30 + 20 * k)), covers_from: '2026-01-01', covers_to: '2066-12-31' }
    expect(check(base({ calendar: long })).status).toBe('CERTIFIED_BY_CONSTRUCTION')
  })
  it('PT-12: the request hash is the Python checker\'s for every request the Python checker reads the same way', () => {
    const cal = { name: 'c', holidays: ['2026-12-25'], covers_from: '2026-01-01', covers_to: '2027-12-31' }
    expect(requestHash(base({ calendar: { ...cal, holidays: ['2026-12-25', '2026-12-25'] } }))).toBe(requestHash(base({ calendar: cal }))) // a frozenset in Python
    const o = base().obligations[0]!
    expect(requestHash(base({ obligations: [{ ...o, note: 'x' } as typeof o] }))).toBe(requestHash(base({ obligations: [o] }))) // not a dataclass field
    // Python's json.dumps escapes U+007F; the Python checker's own hash of this request:
    expect(requestHash(base({ obligations: [{ ...o, id: 'rent\u007f' }] }))).toBe('247e255048cb3411d147572b539305f475b0d4165b20e13f07182b32a07c4ee4')
  })
  it('PT-13: a zero that matured before as_of is not a sovereign claim; horizons must lie after as_of', () => {
    const matured = check(cv({ threshold: 0.3, holdings: [{ id: 'tbill', value_minor: 7_000_000, currency: 'INR', kind: 'sovereign_zero', maturity: '2026-10-20', issuer_is_currency_sovereign: true }, { id: 'equity', value_minor: 3_000_000, currency: 'INR', kind: 'equity_fund' }] }))
    expect(matured.status).toBe('ABSTAIN')
    expect(codes(check(cv({ horizon_end: '2026-11-01' })))).toEqual(['BAD_INPUT'])
    expect(codes(check(pp({ horizon: '2026-11-01', principal_minor: 0, budget_minor: 0, positions: [], risky: [] })))).toEqual(['BAD_INPUT'])
  })
  it('PT-14 and PT-15: charges are dated and zeros pay the face stated, and the certificates say so (enforced since R13)', () => {
    expect(check(pp()).assumptions.join(' ')).toMatch(/the charges listed are every charge to the account before it, on the dates listed/)
    expect(check(cv({ holdings: [{ ...cv().holdings[0], face_minor: 9_100_000 }, cv().holdings[1]] })).assumptions.join(' ')).toMatch(/pay the face stated/)
  })
})
